import{_ as t,c as a,o as i,ae as r}from"./chunks/framework.CliRSA9F.js";const o="/images/episode_rankings.webp",c=JSON.parse('{"title":"Episode Rankings","description":"","frontmatter":{},"headers":[],"relativePath":"features/episode-rankings.md","filePath":"features/episode-rankings.md"}'),s={name:"features/episode-rankings.md"};function n(d,e,l,h,p,g){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="episode-rankings" tabindex="-1">Episode Rankings <a class="header-anchor" href="#episode-rankings" aria-label="Permalink to &quot;Episode Rankings&quot;">​</a></h1><h2 id="track-which-episodes-rank-for-your-keywords" tabindex="-1">Track Which Episodes Rank for Your Keywords <a class="header-anchor" href="#track-which-episodes-rank-for-your-keywords" aria-label="Permalink to &quot;Track Which Episodes Rank for Your Keywords&quot;">​</a></h2><p>Episode Rankings shows how your tracked keywords perform at the episode level. See which of your episodes rank for each keyword on Apple Podcasts and Spotify, giving you insight into content-level performance.</p><p><img src="'+o+'" alt="Episode Rankings Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p>Episode-level rankings are more volatile than show-level rankings, as platforms frequently refresh their search results.</p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="keyword-cards" tabindex="-1">Keyword Cards <a class="header-anchor" href="#keyword-cards" aria-label="Permalink to &quot;Keyword Cards&quot;">​</a></h3><p>Each tracked keyword gets its own card showing:</p><ul><li><strong>Keyword heading</strong> - The search term being tracked</li><li><strong>Ranking status</strong> - Whether any episodes rank for this keyword</li><li><strong>Episode list</strong> - Episodes that appear in search results for this term</li></ul><h3 id="episode-details" tabindex="-1">Episode Details <a class="header-anchor" href="#episode-details" aria-label="Permalink to &quot;Episode Details&quot;">​</a></h3><p>For each ranking episode, you&#39;ll see:</p><ul><li><strong>Episode title</strong> - Which episode is ranking</li><li><strong>Apple Podcasts rank</strong> - Position on AP (if ranking)</li><li><strong>Spotify rank</strong> - Position on SP (if ranking)</li><li><strong>Rank change</strong> - Whether positions improved or declined</li></ul><h3 id="empty-states" tabindex="-1">Empty States <a class="header-anchor" href="#empty-states" aria-label="Permalink to &quot;Empty States&quot;">​</a></h3><p>Keywords without episode rankings show a badge indicating no current rankings. This doesn&#39;t mean the keyword is bad - episode rankings are volatile and may appear over time.</p><h2 id="understanding-episode-rankings" tabindex="-1">Understanding Episode Rankings <a class="header-anchor" href="#understanding-episode-rankings" aria-label="Permalink to &quot;Understanding Episode Rankings&quot;">​</a></h2><h3 id="how-they-differ-from-show-rankings" tabindex="-1">How They Differ from Show Rankings <a class="header-anchor" href="#how-they-differ-from-show-rankings" aria-label="Permalink to &quot;How They Differ from Show Rankings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Show Rankings</th><th>Episode Rankings</th></tr></thead><tbody><tr><td>What ranks</td><td>Your podcast overall</td><td>Individual episodes</td></tr><tr><td>Stability</td><td>More stable</td><td>More volatile</td></tr><tr><td>View structure</td><td>Keywords → platforms</td><td>Keywords → episodes</td></tr><tr><td>Primary use</td><td>SEO strategy</td><td>Content insights</td></tr></tbody></table><h3 id="why-episode-rankings-change-frequently" tabindex="-1">Why Episode Rankings Change Frequently <a class="header-anchor" href="#why-episode-rankings-change-frequently" aria-label="Permalink to &quot;Why Episode Rankings Change Frequently&quot;">​</a></h3><p>Platforms update episode-level search results often based on:</p><ul><li>Fresh content relevance</li><li>Episode engagement metrics</li><li>Search algorithm updates</li><li>User behavior signals</li></ul><p>Expect fluctuation - focus on patterns rather than daily positions.</p><p>Episode Rankings reflects a recent 15-day window of search results, so the rankings you see represent current, up-to-date positions.</p><h2 id="using-episode-rankings-strategically" tabindex="-1">Using Episode Rankings Strategically <a class="header-anchor" href="#using-episode-rankings-strategically" aria-label="Permalink to &quot;Using Episode Rankings Strategically&quot;">​</a></h2><h3 id="identifying-content-hits" tabindex="-1">Identifying Content Hits <a class="header-anchor" href="#identifying-content-hits" aria-label="Permalink to &quot;Identifying Content Hits&quot;">​</a></h3><p>Find episodes that drive keyword visibility:</p><ul><li>Episodes ranking for high-value keywords</li><li>Content that ranks across multiple keywords</li><li>Episodes with stable, consistent rankings</li></ul><h3 id="content-optimization-insights" tabindex="-1">Content Optimization Insights <a class="header-anchor" href="#content-optimization-insights" aria-label="Permalink to &quot;Content Optimization Insights&quot;">​</a></h3><p>Learn what makes episodes rank:</p><ul><li><strong>Title patterns</strong> - Do certain formats rank better?</li><li><strong>Topic depth</strong> - Does comprehensive coverage help?</li><li><strong>Recency</strong> - Are newer episodes ranking more?</li></ul><h3 id="keyword-content-alignment" tabindex="-1">Keyword-Content Alignment <a class="header-anchor" href="#keyword-content-alignment" aria-label="Permalink to &quot;Keyword-Content Alignment&quot;">​</a></h3><p>See if your content matches your keyword strategy:</p><ul><li>Are target keywords driving episode rankings?</li><li>Which episodes rank for unexpected keywords?</li><li>Are there keywords with no episode representation?</li></ul><h2 id="if-no-keywords-are-tracked" tabindex="-1">If No Keywords Are Tracked <a class="header-anchor" href="#if-no-keywords-are-tracked" aria-label="Permalink to &quot;If No Keywords Are Tracked&quot;">​</a></h2><p>Episode Rankings shows your tracked keywords from <a href="/features/show-rankings.html">Show Rankings</a>. If you haven&#39;t added keywords yet:</p><ol><li>Go to Show Rankings or Keyword Strategy</li><li>Add keywords you want to track</li><li>Return to Episode Rankings to see episode-level data</li></ol><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><ul><li><strong>Show Rankings</strong> - Track these same keywords at the show level</li><li><strong>Episode Visibility</strong> - Different view: episodes with their keyword counts</li><li><strong>Keyword Strategy</strong> - Keywords from your strategy feed into tracking</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Episode Rankings is available to Pro subscribers.</p><p><strong>Related Features</strong>: Use <a href="/features/show-rankings.html">Show Rankings</a> for show-level keyword tracking, and <a href="/features/episode-visibility.html">Episode Visibility</a> for an episode-centric view of organic rankings.</p>',40)])])}const u=t(s,[["render",n]]);export{c as __pageData,u as default};
